START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261124064802_AddOptionsDepth5Sidecar') THEN
    CREATE TABLE adaptive_options_depth5_attestation (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "SessionId" bigint NOT NULL,
        "BarSeq" integer NOT NULL,
        "MetricsVersion" character varying(64) NOT NULL,
        "TokenCount" integer NOT NULL,
        "Digests" text NOT NULL,
        "VerifiedAtUtc" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_adaptive_options_depth5_attestation" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_adaptive_options_depth5_attestation_adaptive_sessions_Sessi~" FOREIGN KEY ("SessionId") REFERENCES adaptive_sessions ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261124064802_AddOptionsDepth5Sidecar') THEN
    CREATE TABLE adaptive_options_depth5_bars (
