        "Side" integer NOT NULL,
        "BarSeconds" double precision NOT NULL,
        "Ofi5" bigint,
        "GrossOfi5" bigint,
        "Ofi5Transitions" integer NOT NULL,
        "Ofi5DirectTransitions" integer NOT NULL,
        "Ofi5BridgedTransitions" integer NOT NULL,
        "Ofi5BridgedNet" bigint,
        "Ofi5BridgedGapSeconds" double precision NOT NULL,
        "Ofi5BaselineResets" integer NOT NULL,
        "Tob5TimeWeighted" double precision,
        "MicroDev5TimeWeighted" double precision,
        "DepthImb5TimeWeighted" double precision,
        "BidNotionalTimeWeighted" double precision,
        "AskNotionalTimeWeighted" double precision,
        "Depth5UsableSeconds" double precision NOT NULL,
        "Depth5StaleSeconds" double precision NOT NULL,
        "Depth5InvalidSeconds" double precision NOT NULL,
        "Depth5SupersededSeconds" double precision NOT NULL,
        "Depth5NoDepthSeconds" double precision NOT NULL,
        "Depth5UnobservedSeconds" double precision NOT NULL,
        "SnapshotEvents" integer NOT NULL,
        "SupersededMarkers" integer NOT NULL,
